    /// <summary>A stroke from one of the strings above.</summary>
    public static InkStroke Parse(string points) =>
        new(
            Guid.NewGuid(),
            InkTool.Pen,
            InkColor.FromRgb(0, 0, 0),
            1.42,
            points.Split(' ')
                .Select((p, i) =>
                {
                    var xy = p.Split(',');
                    return new InkPoint(
                        double.Parse(xy[0], CultureInfo.InvariantCulture),
                        double.Parse(xy[1], CultureInfo.InvariantCulture),
                        0.7f,
                        null,
                        null,
                        null,
                        i * 4L);
                })
                .ToArray());
}
